/**
 * Uma proteína por acaso? — o sorteio rodando na tela, sem parar.
 *
 * O número (1 em 10^D) não convence ninguém sozinho: é grande demais para o
 * corpo entender. Esta cena dá ao acaso um sorteio de verdade, ao vivo, e deixa
 * o investigador ver o recorde dele empacar em cinco, seis acertos seguidos
 * enquanto a cadeia funcional pede cento e cinquenta.
 *
 * Cada posição sai certa com probabilidade 1/(2·tipos) — o fator 2 é a forma
 * canhota (L). Errou, recomeça do zero: uma proteína não se monta pela metade.
 *
 * **O relatório para a tela é raro de propósito.** `aoAtualizar` dispara um
 * redesenho do app inteiro; chamá-lo a cada quadro travaria a página. Ele só sai
 * quando o recorde muda, ou a cada 500 ms.
 */

import { criarCanvas2d } from '../../../viz/canvas2d.ts';
import {
  type EstadoDaViz,
  infoDe,
  limitar,
  numeroDe,
  paleta,
  retangulo,
  rodape,
  texto,
  titulo,
} from './desenho.ts';
import type { FabricaViz, VizDoPuzzle } from './index.ts';

/** Os vinte aminoácidos, em código de uma letra. */
const LETRAS = 'ACDEFGHIKLMNPQRSTVWY';

/**
 * Quantos elos cabem na fita desenhada.
 *
 * Não é o limite do que cabe, é o limite do que se LÊ: com quarenta e oito
 * elos o raio cai para uns três pixels e a letra sorteada some. Melhor mostrar
 * vinte e seis grandes e dizer, por escrito, quantos ficaram de fora.
 */
const ELOS_VISIVEIS = 26;

/** Sorteios por quadro: rápido o bastante para impressionar, lento para ler. */
const POR_QUADRO = 3;

const proteina: FabricaViz = (canvas, opcoes): VizDoPuzzle => {
  let estado: EstadoDaViz = {};

  let acertos = 0;
  let recorde = 0;
  let tentativas = 0;
  let ultimaLetra = '';
  let errou = false;
  let ultimoRelato = 0;

  function sortear(tipos: number, alvo: number): void {
    for (let i = 0; i < POR_QUADRO; i++) {
      tentativas++;
      // A chance de a posição sair certa: o aminoácido E a forma canhota.
      const certo = Math.random() < 1 / (2 * Math.max(2, tipos));
      const indice = Math.floor(Math.random() * Math.min(LETRAS.length, Math.max(2, tipos)));
      ultimaLetra = LETRAS[indice] ?? 'A';

      if (certo && acertos < alvo) {
        acertos++;
        errou = false;
        if (acertos > recorde) recorde = acertos;
      } else {
        acertos = 0;
        errou = true;
      }
    }
  }

  function relatar(total: number, agora: number): void {
    if (agora - ultimoRelato < 500) return;
    ultimoRelato = agora;
    opcoes.aoAtualizar?.({ acertos, recorde, total, tentativas });
  }

  function desenhar(ctx: CanvasRenderingContext2D, L: number, A: number, t: number): void {
    const cor = paleta();
    const info = infoDe(estado);

    const total = Math.max(2, Math.round(numeroDe(info, 'aa', 150)));
    const tipos = Math.max(2, Math.round(numeroDe(info, 'tipos', 20)));
    const ok = info.ok === true;
    const funcional = info.real === true;

    sortear(tipos, total);
    relatar(total, t * 1000);

    titulo(ctx, L, A, 'O acaso sorteando a cadeia, elo por elo');

    // ── A fita ────────────────────────────────────────────────────────────
    const x0 = L * 0.05;
    const x1 = L * 0.95;
    const visiveis = Math.min(total, ELOS_VISIVEIS);
    const passo = (x1 - x0) / visiveis;
    const raio = Math.min(passo * 0.42, A * 0.08);
    const yFita = A * 0.38;

    // O cordão que liga os elos: a cadeia é uma coisa só, não contas soltas.
    ctx.strokeStyle = cor.trilho;
    ctx.lineWidth = Math.max(2, raio * 0.32);
    ctx.beginPath();
    ctx.moveTo(x0 + passo * 0.5, yFita);
    ctx.lineTo(x0 + passo * (visiveis - 0.5), yFita);
    ctx.stroke();

    const conquistados = Math.min(acertos, visiveis);
    for (let i = 0; i < visiveis; i++) {
      const cx = x0 + passo * (i + 0.5);
      const preso = i < conquistados;
      const emJogo = i === conquistados;

      ctx.fillStyle = preso ? cor.verde : emJogo && errou ? cor.erro : cor.palha;
      ctx.strokeStyle = preso ? cor.verde : cor.trilho;
      ctx.lineWidth = 1.4;
      ctx.beginPath();
      ctx.arc(cx, yFita, emJogo ? raio * (1 + Math.sin(t * 9) * 0.12) : raio, 0, Math.PI * 2);
      ctx.fill();
      ctx.stroke();

      if (emJogo && raio > 5) {
        texto(ctx, ultimaLetra, cx, yFita, raio * 1.1, {
          cor: errou ? cor.contraste : cor.texto,
          peso: 800,
        });
      }
    }

    if (total > visiveis) {
      texto(
        ctx,
        `… e mais ${total - visiveis} elos`,
        L / 2,
        yFita + raio + limitar(A * 0.045, 10, 14),
        limitar(A * 0.032, 8, 11),
        { cor: cor.fraco, peso: 600 },
      );
    }

    // ── O placar: recorde contra o que a cadeia exige ─────────────────────
    const miudo = limitar(A * 0.036, 9, 13);
    const yBarra = A * 0.62;
    const alturaBarra = limitar(A * 0.055, 9, 16);

    retangulo(ctx, x0, yBarra, x1 - x0, alturaBarra, alturaBarra / 2, cor.palha, cor.trilho, 1);
    retangulo(
      ctx,
      x0,
      yBarra,
      (x1 - x0) * limitar(recorde / total, 0, 1) || 0,
      alturaBarra,
      alturaBarra / 2,
      ok ? cor.verde : cor.azul,
    );

    texto(ctx, `melhor sequência: ${recorde} de ${total}`, L / 2, yBarra - miudo, miudo, {
      cor: cor.fraco,
      peso: 700,
    });
    texto(
      ctx,
      `${tentativas.toLocaleString('pt-BR')} sorteios até agora`,
      L / 2,
      yBarra + alturaBarra + miudo * 1.3,
      miudo * 0.9,
      { cor: cor.fraco, peso: 600 },
    );

    rodape(
      ctx,
      L,
      A,
      ok,
      funcional
        ? 'O acaso alcançaria — mas veja o que a cadeia virou ✔'
        : 'O acaso alcança porque a cadeia deixou de ser proteína ✔',
      `Com ${tipos} tipos, cada elo sai certo 1 vez em ${2 * tipos}.`,
    );
  }

  const base = criarCanvas2d(canvas, {
    aoQuadro: (ctx, { L, A, t }) => desenhar(ctx, L, A, t),
  });

  return {
    aplicar(novo) {
      const antes = infoDe(estado);
      estado = novo;
      const agora = infoDe(estado);
      // Mexer nos parâmetros do sorteio invalida o recorde: ele foi feito com
      // outra loteria. Deixá-lo de pé daria crédito indevido ao acaso.
      if (antes.aa !== agora.aa || antes.tipos !== agora.tipos) {
        acertos = 0;
        recorde = 0;
        tentativas = 0;
        errou = false;
      }
    },
    redimensionar: base.redimensionar,
    pausar: base.pausar,
    retomar: base.retomar,
    destruir: base.destruir,
  };
};

export default proteina;
